using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DeathritePurifyAction", menuName = "Data/Battle/Battle Actions/Moonie/DeathritePurify Action")]
public class DeathritePurifyAction : PurifyCounterBasedAction
{
	[SerializeField]
	private BattleAction dissolveLife;

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetAmountOfActions(dissolveLife, onlyFromHand: false) + 1;
	}
}
